namespace {
uint32_t nextCodepoint(const char*& cursor) {
  const uint8_t* p = reinterpret_cast<const uint8_t*>(cursor);
  if (*p < 0x80) { ++cursor; return *p; }
  uint8_t length = 0;
  uint32_t value = 0;
  if (*p >= 0xC2 && *p <= 0xDF) { length=2; value=*p & 0x1F; }
  else if (*p >= 0xE0 && *p <= 0xEF) { length=3; value=*p & 0x0F; }
  else if (*p >= 0xF0 && *p <= 0xF4) { length=4; value=*p & 0x07; }
  else { ++cursor; return '?'; }
  for (uint8_t i=1; i<length; ++i) {
    if (p[i] == 0 || (p[i] & 0xC0) != 0x80) { ++cursor; return '?'; }
    value = (value << 6) | (p[i] & 0x3F);
  }
  if ((length==3 && value<0x800) || (length==4 && value<0x10000) ||
      (value>=0xD800 && value<=0xDFFF) || value>0x10FFFF) {
    ++cursor; return '?';
  }
  cursor += length;
  return value;
}

const deskui::fontdata::Glyph& glyphFor(uint32_t codepoint) {
  uint16_t low=0, high=deskui::fontdata::kGlyphCount;
  while (low<high) {
    const uint16_t middle = low + (high-low)/2;
    const uint16_t candidate = deskui::fontdata::kGlyphs[middle].codepoint;
    if (candidate<codepoint) low=middle+1;
    else high=middle;
  }
  if (low<deskui::fontdata::kGlyphCount && deskui::fontdata::kGlyphs[low].codepoint==codepoint)
    return deskui::fontdata::kGlyphs[low];
  return deskui::fontdata::kGlyphs['?'-' ']; // The complete printable ASCII set comes first.
}
}  // namespace

namespace deskui {
const char* text(TextId id, Language language) {
  const uint16_t index = static_cast<uint16_t>(id);
  if (index>=static_cast<uint16_t>(TextId::Count)) return "?";
  return kTexts[index][language==Language::English ? 1 : 0];
}

int16_t textWidth(const char* utf8, uint8_t scale) {
  if (!utf8 || scale==0) return 0;
  int32_t width=0, maximum=0;
  while (*utf8) {
    const uint32_t codepoint = nextCodepoint(utf8);
    if (codepoint=='\r') continue;
    if (codepoint=='\n') { if (width>maximum) maximum=width; width=0; continue; }
    width += (codepoint=='\t' ? 32 : glyphFor(codepoint).advance)*scale;
    if (width>32767) width=32767;
  }
  if (width>maximum) maximum=width;
  return static_cast<int16_t>(maximum);
}

void drawText(Adafruit_GFX& gfx, int16_t x, int16_t y, const char* utf8,
              uint16_t color, uint8_t scale) {
  if (!utf8 || scale==0) return;
  int32_t cursorX=x, cursorY=y;
  const int32_t screenWidth=gfx.width(), screenHeight=gfx.height();
  gfx.startWrite();
  while (*utf8) {
    const uint32_t codepoint = nextCodepoint(utf8);
    if (codepoint=='\r') continue;
    if (codepoint=='\n') { cursorX=x; cursorY+=16*scale; continue; }
    if (codepoint=='\t') { cursorX+=32*scale; continue; }
    const fontdata::Glyph& glyph = glyphFor(codepoint);
    if (cursorX<screenWidth && cursorX+glyph.advance*scale>0 &&
        cursorY<screenHeight && cursorY+16*scale>0) {
      for (uint8_t row=0; row<16; ++row) {
        const uint16_t bits=glyph.rows[row];
        uint8_t column=0;
        while (column<glyph.advance) {
          if (!(bits & (0x8000U>>column))) { ++column; continue; }
          const uint8_t first=column;
          while (column<glyph.advance && (bits & (0x8000U>>column))) ++column;
          int32_t left=cursorX+first*scale, top=cursorY+row*scale;
          int32_t right=cursorX+column*scale, bottom=top+scale;
          if (left<0) left=0;
          if (top<0) top=0;
          if (right>screenWidth) right=screenWidth;
          if (bottom>screenHeight) bottom=screenHeight;
          if (right>left && bottom>top)
            gfx.writeFillRect(static_cast<int16_t>(left),static_cast<int16_t>(top),
                              static_cast<int16_t>(right-left),static_cast<int16_t>(bottom-top),color);
        }
      }
    }
    cursorX+=glyph.advance*scale;
  }
  gfx.endWrite();
}
}  // namespace deskui
